window.COBIT_CONTENT_EN = {
  lessons: [
    {
      id:"risk-kontrol-kanit", title:"Start with three words: risk, control, evidence", time:12, level:"From zero", summary:"An employee leaves, but their account stays open. Learn the logic of auditing through a single event.",
      intro:"Before any technical terms, let's start with an everyday question: What could go wrong in a piece of work, and what are we doing about it? That is the foundation of IT auditing. IT means information technology; think of the company's applications, computers, network and data.",
      sections:[
        {title:"Risk: What could go wrong?",text:"If an employee's account stays open after they leave the company, they may be able to access company data. This does not necessarily mean they accessed it or stole data. Risk is about the likelihood and impact of an unwanted event.",bullets:["Event: Unauthorized access by a former employee.","Possible impact: Confidential data being viewed or orders being changed.","Question: Which business outcome could this harm?"]},
        {title:"Control: What do we do to reduce the risk?",text:"HR reports the leaver; an authorized team disables their accounts; the disabling is checked. These steps help prevent or detect the risk occurring. A control can be a tool, a review performed by a person, or a combination of both.",bullets:["Preventive control: Blocking sign-in to the unauthorized account.","Detective control: Regularly searching for former employees' accounts that remain open.","A control should have a clear owner, timing, scope and exception path."]},
        {title:"Evidence: How do we know it was done?",text:"“We disable accounts” is a statement. A system record showing when the account was disabled is evidence that supports it. A list, a log (a record of events), an approval or a test result can all be evidence. A record whose source and scope are unknown may not be as strong as it looks."}
      ],
      example:{title:"Worked example: Deniz's account",story:"The fictional organization's rule is that access is removed when the departure takes effect. Deniz leaves on Monday at 18:00; the ERP account is disabled on Thursday at 10:00. ERP is the enterprise software where work such as orders and inventory is recorded.",steps:["Criterion: The disabling rule set by the organization. Do not mistake this timing rule for a universal COBIT requirement.","Observation: The disabling record for ERP access is roughly three days late.","Follow-up: Was the account blocked at another layer, what permissions did it have, and are the record timestamps correct?","Conclusion: If the evidence is sound, the failure to disable on time is reported. Do not claim data was stolen unless that has been proven."]},
      takeaway:"What could go wrong? → What is being done to reduce it? → What evidence shows that it was done?",
      audit:"Listen to management's explanation, but base your conclusion on appropriate and reliable evidence, not on the explanation. When collecting evidence, do not copy personal data or secrets unnecessarily.",
      exercise:{question:"A company takes a backup every night but has never tried a restore. Write down the risk, the existing control and the evidence you would request, separately.",answer:"Risk: Data or the service cannot be brought back after an outage. Existing control: The backup job; it has not been shown to be sufficient on its own. Evidence: In addition to backup logs, a restore test, an integrity check of the restored data, the measured recovery time and follow-up of failures."},
      source:"Introduction and Methodology, Chapters 1 and 4; the example and basic audit explanations are original training content."
    },
    {
      id:"cobit-nedir",title:"What COBIT is, and what it isn't",time:12,level:"Foundations",summary:"Not a technical checklist: a guide that ties technology decisions to business needs.",
      intro:"COBIT 2019 is a framework that helps an enterprise govern and manage its information and technology so that they contribute to business goals. The framework is not a recipe that decides every detail for you; it is a model that helps you ask the right questions and make the right connections.",
      sections:[
        {title:"Why would a company need this?",text:"A factory buys new production software. IT can get it running; but if it is unclear why the investment was made, what benefit is expected, which risks will be accepted and who is accountable for the result, technology alone will not bring success.",bullets:["Business goal: Make deliveries more reliable.","Technology contribution: Provide accurate and timely planning information.","Management arrangements: Authority, processes, people, information and measurement working together."]},
        {title:"Value is not just about being cheap",text:"When creating value, we consider benefits, risks and resources together. The cheapest backup solution can turn out to be expensive if it stops production for two days. Equally, the most expensive product is not a good investment if it does not meet the business need.",bullets:["Benefit: Which business outcome will improve?","Risk: What could we lose; which uncertainties must we manage?","Resources: How are we using money, people, time and infrastructure?"]},
        {title:"What COBIT does not do",text:"It does not tell you which brand of security product to buy, how many servers to install, or a single control timing that applies to every company. It does not replace standards such as ISO/IEC 27001, service management resources such as ITIL, or technical configuration guides. It can be used alongside them. It covers the use of information and technology across the whole enterprise, not only in the IT department."}
      ],
      example:{title:"Worked example: Is buying a tool a success?",story:"The company bought a monitoring tool. The manager says “the project was a success”, but outages remain at the same level.",steps:["A purchase is a deliverable; it is not a business benefit.","Define the expected benefit: Earlier alerts and shorter outages.","Assign an owner and a metric: For example, the time until response begins for critical incidents.","Besides the tool, also assess the on-call, escalation and training arrangements."]},
      takeaway:"COBIT links technology to the purpose of the business. It does not pick products; it helps you think about which decisions are made, how, and by whom.",
      audit:"Instead of asking “Do you have COBIT?”, ask “Is there adequate control and accountability for this business risk?” The name of a framework is not, on its own, evidence of effectiveness.",
      exercise:{question:"What is missing when a company measures IT success only as “we bought 50 computers this year”?",answer:"The number purchased is a resource/activity indicator. It is unknown whether users do their work better, and what the service quality, risk, total cost and expected business benefit are. Outcomes linked to business goals, and clear ownership, are needed."},
      source:"Introduction and Methodology, Sections 1.3, 3.2 and 4."
    },
    {
      id:"yonetisim-yonetim",title:"Governance and management: who sets the direction?",time:15,level:"Foundations",summary:"Why are a board setting a risk limit and a team disabling an account different kinds of work?",
      intro:"Governance is about deciding which direction to take and overseeing the results. Management plans and carries out the work in line with that direction. Both are necessary; they are not the same concept.",
      sections:[
        {title:"Governance: evaluate, direct, monitor",text:"The enterprise's governing body evaluates stakeholder needs, options and conditions. It sets direction through priorities and decisions. It monitors whether results and compliance are consistent with the direction given. In most companies, ultimate responsibility sits with the board of directors; some authority can be delegated to appropriate structures."},
        {title:"Management: plan, build, run, monitor",text:"Management turns strategy into plans, budgets, projects and day-to-day services. Managers also monitor results. So seeing the word “monitor” does not automatically mean governance.",bullets:["Board: Sets the acceptance limit for critical service risk.","Management: Performs the business impact analysis and prepares the solution plan and resource needs.","Team: Implements the plan, tests it and records the result."]},
        {title:"Accountability and the auditor's boundary",text:"Being accountable means carrying responsibility for an outcome. The person who does the work and the person accountable for the result can be the same; but authority must be clear. An independent auditor evaluates controls. If the auditor takes business decisions in place of management, they may later end up auditing their own decisions."}
      ],
      example:{title:"Worked example: Outage tolerance",story:"At a logistics company, the risk of outages for a critical planning service is rising.",steps:["Governance: Evaluates the business impact and the options, and sets direction for the risk approach.","Management: Prepares a continuity plan and a provider agreement in line with the objectives.","Operations: Runs the recovery test and reports the result.","Audit: Evaluates the authority, the design of the plan and evidence of the actual test."]},
      takeaway:"Governance covers direction and oversight; management organizes execution. Audit provides assurance with appropriate independence.",
      audit:"Check who approved the risk acceptance and the limits of their authority. The auditor does not accept risk on behalf of the company; they report the deficiency and its impact.",
      exercise:{question:"A service manager reviews the monthly SLA report and opens improvement work. Is this governance or management? What does SLA mean?",answer:"It is management: they are monitoring the service level and managing day-to-day/operational improvement. An SLA is a service level agreement; it defines measurable expectations for the service to be delivered and the obligations of the parties."},
      source:"Introduction and Methodology, Sections 1.3 and 4.2."
    },
    {
      id:"bes-alan",title:"See the five domains in one story",time:15,level:"Foundations",summary:"Make sense of the EDM, APO, BAI, DSS and MEA codes without memorizing them.",
      intro:"The 40 objectives in COBIT's core model are divided into five groups. These are called domains. An objective addresses a governance or management outcome to be achieved and the components that support it. Each objective has a related process, but an objective is not just a process.",
      sections:[
        {title:"EDM: Are we heading in the right direction? — 5 objectives",text:"Evaluate, Direct and Monitor: assess, set direction and oversee. This is the governance domain. Benefits, risk, resources, stakeholder relationships and the governance framework are addressed here."},
        {title:"APO: How will we prepare? — 14 objectives",text:"Align, Plan and Organize: align, plan and organize. It sets up management arrangements such as strategy, architecture, budget, people, vendors, risk, security and data."},
        {title:"BAI: How will we put it into practice? — 11 objectives",text:"Build, Acquire and Implement: build, acquire and implement. It covers topics such as defining requirements, building solutions, changes, acceptance/transition, projects, assets and configuration."},
        {title:"DSS: How will we keep it running? — 6 objectives",text:"Deliver, Service and Support: deliver, operate and support the service. Day-to-day operations, incidents/requests, problems, continuity, security services and business process controls belong here."},
        {title:"MEA: How will we understand and assess it? — 4 objectives",text:"Monitor, Evaluate and Assess: monitor, evaluate and review. It covers performance, the system of internal control, compliance with external requirements, and assurance. MEA is also a management domain; the word “monitor” does not make it EDM."}
      ],
      example:{title:"Worked example: A new ordering system",story:"The company wants to offer customers a faster ordering service.",steps:["EDM: Direction is set for the expected benefit and the risk to be accepted.","APO: Strategy, resource and vendor plans are prepared.","BAI: The system is built/acquired, tested and transitioned in a controlled way.","DSS: The system is operated; requests and outages are managed.","MEA: Performance and controls are evaluated; deviations are followed up. Although the domains are described in sequence in this example, in real life they operate at the same time."]},
      takeaway:"5 governance objectives + 35 management objectives = 40. Domains are not departments or one-off project phases.",
      audit:"As a starting point, look at DSS05 access/security, BAI06 changes, DSS01 operations, DSS04 continuity and DSS06 application controls. But business risk should determine the actual scope.",
      exercise:{question:"Which three objectives are candidates for production change approval, a user incident, and compliance with external regulations?",answer:"BAI06 change management; DSS02 service requests and incidents; MEA03 compliance with external requirements. The actual test criterion is then pinned down using the organization's own rule or the applicable external obligation."},
      source:"Introduction and Methodology, Sections 4.2 and 5; Governance and Management Objectives catalog."
    },
    {
      id:"ilkeler-bilesenler",title:"Why isn't writing a procedure enough?",time:20,level:"Foundations",summary:"Learn the six system principles, three framework principles and seven components through everyday examples.",
      intro:"A company has a backup procedure. But when its only expert is on leave, nobody can perform a restore. Having a written process does not mean there is a working governance system.",
      sections:[
        {title:"Six system principles: what should the arrangements you build look like?",bullets:["Provide stakeholder value: Look at business benefit, risk and resources, not just the number of devices.","Holistic approach: Processes, people, information and tools must work together.","Dynamic governance system: Reassess the arrangements during changes such as moving to the cloud.","Governance distinct from management: Separate setting direction from execution.","Tailored to enterprise needs: A small business and a bank do not need the same design.","End-to-end governance system: Software that a business unit buys on its own is also part of the scope."]},
        {title:"Three framework principles: what should the model you use look like?",bullets:["Based on a conceptual model: The parts and the relationships between them should be consistent.","Open and flexible: It should be adaptable to new topics.","Aligned to major standards: It should be usable alongside other important frameworks, standards and regulations."]},
        {title:"Seven components: what do we design together?",bullets:["Processes: What steps are followed to perform a restore test?","Organizational structures: Who is the owner, who is authorized, and what is the oversight structure?","Principles, policies and procedures: What are the written rules and ways of working?","Information: Where are the test result, the timing measurement and the error report kept?","Culture, ethics and behavior: Are problems hidden, or is reporting them encouraged?","People, skills and competencies: Is there a trained backup person who can do the work?","Services, infrastructure and applications: Are the required tools and environment working?"]}
      ],
      example:{title:"Worked example: A procedure exists, but no tests",story:"The team has not performed a restore test for a year. The manager only shows the procedure.",steps:["Process: Create a test schedule that fits the risk and the business need.","Structure: Assign the test owner and the role that will review the results.","People: Build hands-on competence in more than one person.","Information: Record the actual duration, data validation and open actions.","Behavior: Treat a failed test as an opportunity to fix things rather than hiding it."]},
      takeaway:"A process alone is not enough. System principles describe the arrangements within the enterprise; framework principles describe the model being used.",
      audit:"Don't just ask for the procedure. Also look at the authority, training, actual transaction records, information quality and tool settings that support it.",
      exercise:{question:"“We bought a new monitoring tool, but it isn't clear who responds when an alert comes in.” Which components may be missing?",answer:"Organizational structures and responsibilities; the incident/escalation process; policy/procedure; staff competence and on-call arrangements. The tool covers only one part of the seven components."},
      source:"Introduction and Methodology, Chapter 3 and Section 4.3."
    },
    {
      id:"hedef-zinciri",title:"Link business needs to controls",time:18,level:"Connect",summary:"Before saying “let's disable accounts”, find out which business goal you are protecting.",
      intro:"If you cannot explain why a control is performed, you may just be ticking boxes. The goals cascade helps link a stakeholder need to an enterprise goal, the technology contribution and the related COBIT objectives.",
      sections:[
        {title:"Four steps",bullets:["Stakeholder need: The customer wants to receive their order on the promised day.","Enterprise goal: On-time and reliable delivery.","Alignment goal: Information and technology services should provide the continuity and accuracy that delivery needs.","Governance/management objectives: Relevant areas such as continuity, availability, data, change or vendor management."]},
        {title:"What does alignment mean?",text:"It means that technology efforts serve the outcome the business wants. It is not just IT's own internal efficiency. COBIT 2019 has 13 enterprise goals and 13 alignment goals. The examples here use plain, informal wording; they are not the official EG/AG code mapping."},
        {title:"Separate outcomes from activities",text:"“We delivered training”, “we bought a tool” or “we reviewed 100 records” describe activities. “Unauthorized access decreased” or “the share of shipments delayed because of IT fell” relate to outcomes. Both can be monitored, but they do not answer the same question."}
      ],
      example:{title:"Worked example: Keep shipments on track",story:"Shipments are delayed because of ERP outages.",steps:["Business goal: Reduce IT-related delivery delays.","Technology contribution: The critical service runs/recovers in line with business needs.","Candidates: DSS04 continuity; BAI04 availability/capacity; BAI06 changes; APO09 service agreements.","Business indicator: Shipments delayed due to IT / total shipments.","Supporting measure: Availability of the critical service, with a defined scope. Do not automatically attribute every delay to IT."]},
      takeaway:"Business goal → technology contribution → relevant objectives → controls → evidence and measurement. The links are mostly many-to-many.",
      audit:"If you are going to rely on an automated business control, assess whether the related access, change and operations controls support that reliance.",
      exercise:{question:"Which business goal is protected by a control that prevents unauthorized changes to a vendor's bank account? What would you request as evidence?",answer:"It protects payments being made accurately to the correct, authorized payee, and prevents loss. Request the population of master data changes, the authorization and approval matrix, the change log, independent verification and actual transaction records. DSS06 and APO14 are candidate links; a code alone is not a sufficient criterion."},
      source:"Introduction and Methodology, Section 4.6; Governance and Management Objectives, mapping appendices."
    },
    {
      id:"kuruma-uyarlama",title:"The same controls in every company?",time:20,level:"Connect",summary:"Choose the right priorities using the 11 design factors and focus areas.",
      intro:"A bank and a small design office do not face the same technology risks. COBIT offers a common model, but the priority of objectives, the design of components and the target capability levels are set according to context.",
      sections:[
        {title:"11 design factors",bullets:["Enterprise strategy: Emphasis on growth, innovation, cost or stability.","Enterprise goals: What do we want to achieve in the business?","Risk profile: Which risks matter, and how much?","Current I&T-related issues: What is going wrong right now?","Threat landscape: Which external/internal threats do we face?","Compliance requirements: Regulations, contracts and other obligations.","Role of IT: Is it supportive or strategic, and how critical is it to operations?","Sourcing model for IT: In-house team, outsourcing, cloud or a mixed model.","IT implementation methods: How do we develop and deliver solutions?","Technology adoption strategy: Are we early adopters, or do we wait for technology to mature?","Enterprise size: Scale, complexity and resources."]},
        {title:"What is a focus area?",text:"It is a governance approach tailored to a specific topic, such as cybersecurity, DevOps, small and medium-sized enterprises or digital transformation. It is not a new, sixth domain. It can bring together the relevant objectives and components."},
        {title:"Design in four steps",bullets:["1. Understand the enterprise context and strategy.","2. Determine the initial scope: Start from goals, risks and current issues.","3. Refine the scope using the other design factors.","4. Resolve priority conflicts and conclude the design."]},
        {title:"Priority order is not something to memorize",text:"DSS04 may stand out in an organization where production continuity is critical. Elsewhere, data quality or privacy may dominate. Risk-based selection is not permission to ignore mandatory external obligations. The examples here are not official Design Toolkit scoring."}
      ],
      example:{title:"Worked example: ERP at an external provider",story:"ParçaNova's critical production planning system is run by an external provider; there are frequent version upgrades and long outages.",steps:["Outsourcing model: APO10 vendor management comes to the fore.","Critical service: DSS04 continuity and BAI04 availability become important.","Change problem: BAI06 and BAI07 are reviewed.","Balance speed and security: Design different change paths according to risk, with adequate testing and approval."]},
      takeaway:"It is not mandatory to implement all 40 objectives to the same depth or to raise every process to the highest level.",
      audit:"When selecting the scope, justify it with critical services, data, major changes, privileged access, past findings and external requirements.",
      exercise:{question:"Why might it be a problem to leave the existing audit plan completely unchanged when the company moves to the cloud?",answer:"The split of responsibilities, the access model, provider dependency, logs, data location and recovery paths may all have changed. In line with the dynamic system principle and the design factors, the impact is assessed and the scope is updated."},
      source:"Introduction and Methodology, Sections 4.4–4.5 and 7."
    },
    {
      id:"roller-ve-kontrol",title:"Who performs the control, and who is accountable?",time:18,level:"Apply",summary:"RACI, segregation of duties, and the difference between objective, practice and activity.",
      intro:"Saying “changes are properly approved” is vague. Who approves? When? Which transactions? With what record? To make a control auditable, you need to answer these questions.",
      sections:[
        {title:"Objective, practice, activity",bullets:["Objective: Managing IT changes; BAI06.","Practice: Evaluating, prioritizing and authorizing change requests; for example, BAI06.01.","Activity: Reviewing the business impact and test results of a specific change and recording the decision. This concrete sentence is a training example."]},
        {title:"RACI: Four different roles",bullets:["R — Responsible: The person who does the work.","A — Accountable: The person answerable for the outcome, carrying responsibility within their authority.","C — Consulted: The person whose opinion is sought.","I — Informed: The person who is kept informed.","Using a single A in training tables improves clarity. A real design follows the organization's authority model; this is not a copy of an official role matrix."]},
        {title:"Why is segregation of duties needed?",text:"If one person can create a vendor, change its bank account and also approve the payment, they could make and hide an error or fraud on their own. Separating permissions reduces the risk. When separation is hard in a small team, it must be shown that compensating controls, such as an independent review, actually work."},
        {title:"Parts of a well-written control",text:"Owner + scope + trigger/frequency + review to be performed + decision/exception + retained evidence. Example: For normal ERP changes, the business impact and test/rollback readiness are assessed by an authorized manager before go-live and approved with a timestamp. Emergencies have their own separate, authorized and traceable path."}
      ],
      example:{title:"Worked example: The roles in a change",story:"Assume the organization has defined the authorities for production system changes.",steps:["Service owner: Sets the business acceptance expectations.","Change manager: Runs the assessment/approval within their authority.","Operations: Implements the approved change and records the result.","Auditor: Independently evaluates the design and operation of the control; does not take on approval of normal changes."]},
      takeaway:"A code or a procedure does not make a control work by itself. Ownership, authority and evidence must be clear.",
      audit:"Don't stop at seeing the signature on an access review. Verify that inappropriate access that was identified was actually removed and that exceptions were handled by authorized people.",
      exercise:{question:"A developer can approve their own code alone and deploy it to production. What is the risk, and what would you investigate?",answer:"The risk of faulty/unauthorized changes without independent review. I would review the actual permissions, approval and deployment logs, role combinations, mandatory tests and any independent compensating control. Having access is not, on its own, evidence of misuse."},
      source:"Governance and Management Objectives, Chapter 3 and BAI06; Introduction and Methodology, Section 6.5.1."
    },
    {
      id:"olcum-yetkinlik",title:"How do you know it is working well?",time:20,level:"Apply",summary:"Percentages, KPIs/KRIs, 0–5 capability, and how it differs from maturity.",
      intro:"There may be many controls, yet the business outcome can still be poor. Measurement helps you understand what is going well and what needs improving. But a nice percentage calculated from wrong data is misleading.",
      sections:[
        {title:"Performance and risk indicators",text:"A KPI is a key performance indicator that tracks how far a goal is being achieved. A KRI is a key risk indicator that helps track exposure to risk and how it changes. The same measure can serve either purpose, depending on the decision it supports. Every metric needs a clear definition, unit, scope, data source, frequency, owner and target."},
        {title:"Process capability: what does 0–5 tell you?",bullets:["0: No basic capability, or an incomplete approach.","1: Initial; the process partly achieves its purpose through incomplete activities.","2: The process achieves its purpose through a basic but complete set of activities.","3: A more organized, defined process that makes use of organizational assets.","4: Process performance is measured quantitatively.","5: Continuous improvement driven by measurement.","These are teaching summaries. Assigning an official level requires the relevant activities, the requirements of the lower levels, evidence and an appropriate assessment method."]},
        {title:"Is maturity the same thing?",text:"No. Capability is assessed at process level, whereas maturity describes the more holistic performance of a focus area. The related process and component requirements are considered together. Averaging the scores of a few processes, or declaring the company's maturity based on one good process, is not correct."},
        {title:"Is everyone's target 5?",text:"No. A target capability level is justified by business needs, risk and resources. The existence of a procedure document is not enough to say “3”, and the existence of a dashboard is not enough to say “4”."}
      ],
      example:{title:"Worked example: Two simple measures",story:"6 of 40 changes failed. There were 3.6 hours of service outage in a 720-hour measurement period.",steps:["Failed change rate: 6 / 40 × 100 = 15%.","Availability: (720 − 3.6) / 720 × 100 = 99.5%.","If the training targets are at most 10% and at least 99.8%, neither was met.","Whether planned maintenance and provider outages count must be defined up front; they cannot be quietly excluded to make the result look better."]},
      takeaway:"Metrics help you understand business outcomes; capability, how a process is carried out; maturity, the focus area as a whole.",
      audit:"Before using a report, check its filters, date range, missing records and reconciliation to the source. A good sample cannot be drawn from an incomplete population.",
      exercise:{question:"8 out of 100 changes caused service degradation. What is the rate? Does this information alone show the process capability level?",answer:"8 / 100 × 100 = 8%. No; this is a performance result. Determining a level requires evaluating evidence of the related process activities, systematic execution and the other requirements."},
      source:"Introduction and Methodology, Sections 6.1–6.5. Numerical thresholds are training examples."
    },
    {
      id:"denetim-nasil-yapilir",title:"How is an IT audit done, step by step?",time:25,level:"Auditor's lens",summary:"The logic of a working paper, from scope to sampling and from finding to closure.",
      intro:"Auditing is not hearing management describe a control and saying yes. You must be able to show the subject, the period, the criterion and the evidence on which your conclusion is based.",
      sections:[
        {title:"1. Objective, scope and criteria",text:"The objective states which risk you want assurance over. The scope sets the boundaries: systems, entities, period and transaction types. The criterion is the expected state: applicable laws and regulations, a contract, an approved policy or a clearly agreed control rule. A COBIT code gives the review structure but does not, on its own, provide the criterion for every detail."},
        {title:"2. Separate design from operation",text:"Design: If the control works as described, does it adequately address the risk? Operation: Did it actually work during the selected period? A policy is one element of design. The period's approvals and system records can be evidence of operation. Following a single transaction from start to finish, known as a walkthrough, helps you understand the flow; on its own it is not sufficient for the whole period."},
        {title:"3. Population and sample",text:"The population is all the records that fit the purpose of the review. First check that the population is complete and accurate. Then select a sample based on risk, frequency, method, expected deviation and purpose. There is no fixed “COBIT sample size” that fits every situation. Do not present a risk-based selection as if it were statistically representative."},
        {title:"4. Finding and risk",text:"Criterion + observed condition + evidence-supported cause + risk/impact + action. If the cause is unknown, state that it needs to be investigated. Do not write as if actual damage or fraud occurred unless it has been proven. Justify the severity using likelihood, impact, pervasiveness and compensating controls."},
        {title:"5. Closure and independence",text:"Each action must have a named owner and a target date. “We delivered training” or a new procedure is not, on its own, closure; retest that the fix works. Do not confuse management's monitoring of a control with independent assurance."}
      ],
      example:{title:"Worked example: Late approval",story:"The organization's policy requires prior approval for normal changes. Of 80 records in October, 20 were selected on a risk basis; in 4 of them, approval came after go-live.",steps:["The rate observed in the sample is 20%. We cannot say that exactly 20% of the population is problematic.","Verify the time zone, record integrity, approval authority and the normal/emergency classification.","Risk: Changes can reach production without their business impact being reviewed; do not assume that an actual outage occurred.","Action: Fix the approval path; verify it on the next period's actual records and through an authorized, controlled test."]},
      takeaway:"A conclusion is only as strong as its testing and evidence. Do not make definitive statements that go beyond the scope.",
      audit:"You can use inspection, observation, reperformance and appropriate data analysis. Performing transactions in production or active technical testing additionally requires explicit authorization and a safe plan.",
      exercise:{question:"The organization says “we perform access reviews” and provides a signed list. What else would you ask about operation?",answer:"Does the list cover all relevant accounts and permissions? Is the reviewer authorized and adequately informed? Against what criteria did they review? Did they find anything inappropriate? Were the removal/approved-exception actions completed? I would verify against system records and the permissions in place after remediation."},
      source:"Introduction and Methodology, Chapter 6; Governance and Management Objectives, MEA02/MEA04 and related objectives. The audit steps are original general training notes."
    },
    {
      id:"itgc-uygulama",title:"Tell ITGCs apart from application controls",time:20,level:"Auditor's lens",summary:"Understand how an invoice rule connects to system access controls.",
      intro:"ITGCs are IT general controls. Think of the access, change and operations controls that lay the groundwork for many applications to run reliably. An application control, by contrast, helps a specific business transaction to be accurate, complete, valid and authorized.",
      sections:[
        {title:"ITGC examples",bullets:["Removing access for people who leave.","Moving production code changes through authorized approval/testing.","Monitoring failed critical jobs and following up on errors.","Backup and recovery arrangements in line with business needs."]},
        {title:"Application control examples",bullets:["Blocking a second invoice with the same vendor/invoice number.","Requiring authorized approval for orders above a set amount.","Reconciling record counts and amounts between source and target in an interface.","Independently verifying changes to vendor bank accounts."]},
        {title:"Why do we review them together?",text:"A duplicate invoice control may be working today. But if an unauthorized person can change the rule, confidence that it worked throughout the period decreases. So you review the related access and change controls. An ITGC weakness does not automatically invalidate all application controls; you assess the affected layer, control, period and alternative evidence."},
        {title:"Reports, interfaces and Excel files",text:"If a person performs a control by looking at a report, the completeness/accuracy of that report also matters. Data can be lost or processed twice in an interface. In end-user tools such as Excel, consider the risks around formulas, versions, access, source data and review."}
      ],
      example:{title:"Worked example: Paid twice",story:"The finance team says the system blocks duplicate invoices.",steps:["Clarify the rule: Which combination of fields, and which exceptions?","In an authorized test environment, verify the expected blocking and the permitted exception.","Check who can change the rule and whether it changed during the period.","In real data, review duplicates, blocked/excepted transactions and evidence of follow-up.","Limit the conclusion to the scope of this control and the period reviewed."]},
      takeaway:"ITGCs support the environment; application controls protect the business transaction. Explain the link between the two.",
      audit:"DSS06 and APO14 are starting links for business/data controls; DSS05, BAI06 and DSS01 are starting links for the supporting general controls.",
      exercise:{question:"Why is “the monthly report was produced” different from “a control was performed using the report”?",answer:"Producing a report creates information. A control requires an authorized person to review an accurate/complete report against defined criteria, investigate exceptions and follow up on actions. Evidence of this review and follow-up is also sought."},
      source:"Governance and Management Objectives, DSS06, APO14, DSS05, BAI06 and DSS01; the examples are original."
    },
    {
      id:"uygulama-yol-haritasi",title:"Turn what you have learned into lasting practice",time:20,level:"Bring it together",summary:"Seven implementation phases, a 90-day example and a professional learning plan.",
      intro:"Implementing COBIT is not filling in a PDF or buying a tool. Arrangements designed around real needs must become part of day-to-day work and deliver measurable benefit.",
      sections:[
        {title:"Seven implementation questions",bullets:["1. What are the drivers? What is the problem, risk or opportunity?","2. Where are we now? What do the current state and the evidence show?","3. Where do we want to be? What is a realistic target?","4. What needs to be done? Which work will close the gap?","5. How do we get there? What are the plan, people, resources and ownership?","6. Did we get there? What do the results and benefits show?","7. How do we keep the momentum going? How will regular review and ownership continue?"]},
        {title:"Don't confuse design with implementation",text:"The four-step design flow helps determine what kind of governance system is needed. The seven-phase implementation approach deals with putting the change into practice and sustaining it. They support each other; they are not the same list. Change management and program management also matter."},
        {title:"What should you study next?",text:"First choose one service or control family. Map the workflow, write down the risks, build the COBIT links, set the criteria and create a sample working paper. Then go deeper into the relevant technical resource or standard. This site explains the direction of the 40 objectives; it does not reproduce all of the official practices/activities or professional standards."}
      ],
      example:{title:"Worked example: A 90-day start",story:"A critical ERP service has change and restore problems. The timings are a fictional training plan.",steps:["Days 0–30: Verify the business impact and the records; assign owners and baseline indicators.","Days 31–60: Fix change permissions and the change flow; run a recovery test that includes dependencies; train a second person.","Days 61–90: Evaluate operation in the new period; close open actions; review the results with the business owner.","Sustain: Embed the test schedule, metric owners and regular governance reviews into day-to-day work."]},
      takeaway:"Improvement lasts when there is a responsible person + an implemented control + real evidence + a monitored business outcome.",
      audit:"Audit recommendations should be practical, but management owns the solution. At closure, evaluate the adequacy and operation of the fix, not the document.",
      exercise:{question:"Why wouldn't you immediately accept “a new security tool was bought, so the finding is closed”?",answer:"It is unknown whether the tool actually addresses the risk, whether it runs with the right scope and settings, whether the responsible people respond, what evidence from a real period shows, and what the business impact is. An appropriate closure test and an assessment of the remaining risk are needed."},
      source:"Introduction and Methodology, Chapters 7–8; for further professional practice, current official sources should also be used."
    }
  ],
  domains:{
    EDM:{name:"Direct and oversee",full:"Evaluate, Direct and Monitor",kind:"Governance",description:"Oversight of enterprise direction, benefits, risk, resources and stakeholders."},
    APO:{name:"Plan and organize",full:"Align, Plan and Organize",kind:"Management",description:"Strategy, resources and management arrangements."},
    BAI:{name:"Put into practice",full:"Build, Acquire and Implement",kind:"Management",description:"Solutions, projects and changes."},
    DSS:{name:"Run and support",full:"Deliver, Service and Support",kind:"Management",description:"Day-to-day services, continuity and operational controls."},
    MEA:{name:"Monitor and evaluate",full:"Monitor, Evaluate and Assess",kind:"Management",description:"Performance, internal control, compliance and assurance."}
  },
  objectives:[
    ["EDM01","Governance framework","Ensured Governance Framework Setting and Maintenance","Addresses how decisions, authority and oversight are organized.","Who owns which decision, and are these arrangements up to date?","Board/committee authorities, governance policy, decision and review records."],
    ["EDM02","Benefits realization","Ensured Benefits Delivery","Oversees that technology investment turns into the expected business benefit.","Why was the investment made, and who is tracking the benefit?","Business case, benefit owners, actual results and board reviews."],
    ["EDM03","Balancing risk","Ensured Risk Optimization","Oversees that technology-related risk is consistent with the enterprise's approach to accepting risk.","Who sets direction on risk limits, and how are deviations handled?","Risk approach, authorized risk decisions and senior-level risk reports."],
    ["EDM04","Balancing resources","Ensured Resource Optimization","Oversees that resources such as people, technology and money are used in line with business needs.","Is a resource gap or unnecessary duplication affecting business goals?","Resource capacity, investment/people plans and oversight decisions."],
    ["EDM05","Stakeholder engagement","Ensured Stakeholder Engagement","Oversees that stakeholder communication and reporting meet needs.","Do the right stakeholders receive the right information on time?","Stakeholder map, reporting expectations and communication records."],
    ["APO01","Management framework","Managed I&T Management Framework","Sets up the roles, rules and ways of working for managing technology.","Are policies, ownership and processes consistent with each other?","Management policies, process owners, role and review records."],
    ["APO02","Strategy","Managed Strategy","Turns business direction into technology goals and a roadmap.","Which business goal does the technology plan contribute to?","Business/IT strategy, gap analysis, roadmap and monitoring."],
    ["APO03","Enterprise architecture","Managed Enterprise Architecture","Addresses the joint design of business, data, application and technology structures.","Is the new solution consistent with the current structure and the target design?","Architecture models, standards and architecture decisions."],
    ["APO04","Innovation","Managed Innovation","Assesses the value, suitability and risk of new ideas and technologies.","Does the new technology really solve a business need?","Idea assessments, pilot results and risk/benefit analyses."],
    ["APO05","Portfolio","Managed Portfolio","Manages sets of investments, services and assets together with business priorities.","Are we allocating resources to the right initiatives?","Portfolio decisions, priority/resource and benefit tracking records."],
    ["APO06","Budget and costs","Managed Budget and Costs","Covers planning, monitoring and making technology spending transparent.","Is there a clear owner and business rationale for the cost?","Budget, actual spending, cost model and variance reviews."],
    ["APO07","People","Managed Human Resources","Manages the required people capacity, skills and responsibilities.","Is there a competent backup person for critical work?","Competency/staffing plan, training and role assignments."],
    ["APO08","Relationships","Managed Relationships","Manages the expectations of business and technology stakeholders and the collaboration between them.","How are the business unit's needs and dissatisfaction understood?","Relationship meetings, expectations, issue and action records."],
    ["APO09","Service agreements","Managed Service Agreements","Defines and agrees service expectations and tracks the results.","Does the SLA reflect business needs, and is it measured correctly?","Service catalog, SLA, service reports and deviation actions."],
    ["APO10","Vendors","Managed Vendors","Manages the selection, obligations, risk and performance of external providers.","Are control responsibilities clear for outsourced work?","Contract, responsibility matrix, vendor assessments."],
    ["APO11","Quality","Managed Quality","Manages whether solutions and services meet quality expectations.","Are quality criteria and a way of fixing defects defined?","Quality plan, acceptance criteria, reviews and improvement records."],
    ["APO12","Risk management","Managed Risk","Collects and analyzes risk data and manages the risk profile and responses.","Are the risk scenario, its owner and the response up to date?","Risk register, analyses, response and monitoring records."],
    ["APO13","Security management","Managed Security","Sets up the management arrangements and risk-based plan for information security.","Are security objectives and responsible people defined?","Security policy, scope, risk plan and management reviews."],
    ["APO14","Data management","Managed Data","Covers the data life cycle, quality, ownership and management.","Is the data accurate and meaningful, and does it have a clear owner?","Data owners, definitions, quality rules and life cycle records."],
    ["BAI01","Programs","Managed Programs","Coordinates multiple related changes so that they achieve the expected benefits.","Do the projects together deliver the intended business outcome?","Program rationale, dependencies, benefit and oversight records."],
    ["BAI02","Requirements","Managed Requirements Definition","Clarifies the solution requirements the business needs.","Are the acceptance conditions for the requested solution correct and approved?","Requirements, traceability, feasibility and acceptance approvals."],
    ["BAI03","Building solutions","Managed Solutions Identification and Build","Manages the selection, development and building of solutions with adequate quality.","Does the solution meet business and security requirements?","Design, development, quality/test records and solution components."],
    ["BAI04","Availability and capacity","Managed Availability and Capacity","Manages whether the service runs when needed and with sufficient capacity.","How do peak load and failures affect the service?","Capacity plan, availability measurements and improvement records."],
    ["BAI05","Organizational change","Managed Organizational Change","Supports people in adopting new ways of working and helps change take hold.","Can people actually use the new solution?","Change/communication plan, training, readiness and adoption measures."],
    ["BAI06","IT changes","Managed IT Changes","Manages system changes so that they are made with appropriate assessment, authorization and traceability.","Is the production change tested, authorized and ready for rollback?","Change population, approval/test, deployment and emergency change records."],
    ["BAI07","Acceptance and transition","Managed IT Change Acceptance and Transitioning","Covers the acceptance of new or changed solutions and their safe transition into operation.","Are the business and operations ready to take on the solution?","Acceptance tests, transition plan, operational readiness and post-implementation review."],
    ["BAI08","Knowledge","Managed Knowledge","Ensures that the knowledge and experience the business needs are findable, current and usable.","Does critical knowledge exist only in one person's head?","Knowledge base, ownership, currency and usage reviews."],
    ["BAI09","Assets","Managed Assets","Manages technology assets throughout their life cycle.","Which asset belongs to whom, what condition is it in, and under what obligations is it used?","Inventory, ownership, licensing and acquisition/disposal records."],
    ["BAI10","Configuration","Managed Configuration","Accurately tracks the structure and relationships of service components.","If a component changes, which service is affected?","Configuration records, relationships and verification results."],
    ["BAI11","Projects","Managed Projects","Covers managing individual projects in terms of scope, time, resources and quality.","Is the delivery aligned with business expectations and acceptance conditions?","Project plan, risk/issue log, progress and acceptance records."],
    ["DSS01","Operations","Managed Operations","Covers the planned and reliable running of day-to-day technology services.","Are failed critical jobs and alerts followed up?","Job scheduler, operating procedures, alert and response records."],
    ["DSS02","Requests and incidents","Managed Service Requests and Incidents","Records and resolves user requests and outages, and restores service.","Are the incident's business impact, priority and resolution correct?","Ticket population, priority/escalation, time and resolution records."],
    ["DSS03","Problems","Managed Problems","Addresses the causes of recurring incidents and permanent fixes.","Why does the same issue keep happening?","Problem/root cause records, known errors and permanent actions."],
    ["DSS04","Continuity","Managed Continuity","Manages keeping critical business operations/services running and recovering them during a disruption.","Does tested recovery meet business needs?","Business impact analysis, continuity plan, restores/tests and actions."],
    ["DSS05","Security services","Managed Security Services","Covers operational protections such as access, endpoints, network and security monitoring.","Are unauthorized access and security incidents prevented/detected?","Accounts/permissions, security configuration, log and incident reviews."],
    ["DSS06","Business process controls","Managed Business Process Controls","Supports business transactions being carried out in an authorized, complete, accurate and reliable way.","How are transaction errors or inappropriate transactions prevented and detected?","Business rules, authorization/SoD, reconciliations, exceptions and follow-up evidence."],
    ["MEA01","Performance and conformance monitoring","Managed Performance and Conformance Monitoring","Measures and reports results and conformance with rules, and follows up deviations.","Is the metric correct, and is there an action for the deviation?","Indicator definitions, source data, reports and action tracking."],
    ["MEA02","System of internal control","Managed System of Internal Control","Monitors the adequacy of the control system and addresses gaps.","Are control design and operation evaluated regularly?","Control assessments, deficiencies, owners and remediation."],
    ["MEA03","Compliance with external requirements","Managed Compliance With External Requirements","Identifies applicable external obligations, assesses compliance and follows up.","Which obligation is met by which control?","Obligations inventory, compliance assessment and actions."],
    ["MEA04","Assurance","Managed Assurance","Covers planning and performing assurance work according to risks and needs.","Is the assurance scope adequate, the method appropriate and the result followed up?","Assurance plan, working papers, reports and finding follow-up."]
  ],
  glossary:[
    ["Risk","Uncertainty about the likelihood and impact of an unwanted event. An open account creates risk; on its own it does not prove misuse."],
    ["Control","An action or arrangement carried out to reduce a risk or to help achieve a goal. For example, access approval."],
    ["Evidence","Reliable information or records that support an assessment. Its source, period and scope matter."],
    ["Criterion","The benchmark that defines the expected state, such as an applicable policy, contract or regulation."],
    ["Governance","The arrangements for evaluating needs, setting direction and overseeing results."],
    ["Management","Planning, building, running and monitoring in line with the direction that has been set."],
    ["Stakeholder","A party affected by, or able to influence, a decision, such as customers, employees, the board or regulators."],
    ["Alignment","Information and technology efforts serving business goals."],
    ["Process","An organized set of interrelated activities aimed at achieving a result."],
    ["Practice","In this context, a governance/management practice within a process. It does not necessarily refer to a software application."],
    ["Activity","A more concrete task or step that carries out a practice."],
    ["Component","One of the parts of a governance system, such as processes, people, structures, information or tools."],
    ["Focus area","An approach that brings together the relevant objectives and components for a topic such as cybersecurity or DevOps."],
    ["ITGC","IT general controls. Access, change and operations controls that support many applications."],
    ["Application control","A control aimed at the accuracy, completeness, authorization and validity of specific business transactions."],
    ["SoD / segregation of duties","An approach to preventing or detecting combinations of permissions that would let one person make and hide an error or inappropriate transaction."],
    ["RACI","R: does the work; A: accountable; C: consulted; I: informed."],
    ["SLA","Service level agreement: measurable service expectations and the obligations of the parties."],
    ["ERP","Enterprise resource planning software that supports business processes such as orders, inventory, production and finance in one place."],
    ["Log","A record of system events and transactions with details such as the time. Whether it can be altered, and what it covers, are assessed."],
    ["MFA","Multi-factor authentication: using more than one verification factor of different types."],
    ["Privileged account","A high-privilege account that can administer the system or important settings."],
    ["Service account","An account used by an application or automated job; it may not be used in the same way as a human account."],
    ["RTO","Recovery time objective. How quickly the service needs to be restored to meet business needs."],
    ["RPO","The target for acceptable data loss, expressed as time. For example, a tolerance for losing the last hour of data."],
    ["BIA / business impact analysis","An analysis to understand how a disruption affects the business and what the critical needs are."],
    ["KPI","Key performance indicator; helps measure progress toward a goal."],
    ["KRI","Key risk indicator; helps monitor exposure to risk and how it changes."],
    ["Capability","In this context, the level of performance relating to how a process is implemented and how it operates."],
    ["Maturity","A more holistic performance concept at focus area level; it is not a simple average of process scores."],
    ["Population","All the records that fit the defined purpose, period and scope."],
    ["Sample","The part of the population selected for assessment. The selection method affects how the results can be interpreted."],
    ["Walkthrough","Following a transaction from start to finish to understand the flow and the control points."],
    ["Design adequacy","The question of whether a control, if operated as planned, reasonably addresses the related risk."],
    ["Operating effectiveness","Whether the control was applied as designed during the period reviewed."],
    ["Finding","A proven difference between the expected criterion and the observed condition, together with an explanation of its risk/impact."],
    ["Compensating control","A control that helps address, by an alternative route, the risk arising from a missing or deficient primary control."],
    ["SOC report","A family of independent assurance reports on a service organization. It should not be treated as general assurance without reading its scope, type, period and exceptions."],
    ["UAT","User acceptance testing: assessing whether a solution meets business expectations."],
    ["CI/CD","An approach that supports code integration and delivery/deployment steps with automation. Automation alone does not prove that controls are adequate."]
  ],
  cases:[
    {id:"acik-hesap",title:"The account left open",tag:"Beginner",time:15,story:"At the fictional MaviLojistik, 12 people leave in June. The departures are on the HR list. Three of the ERP accounts appear to have been disabled five days later. The manager says “they didn't log in anyway”. The access policy states that accounts must be disabled at the moment the departure takes effect.",
      tasks:["Write down the business risk and the criterion.","Identify at least four pieces of evidence to request.","Distinguish a delayed record from an actual data theft.","Propose a test and a closure condition."],
      solution:["Risk: Unauthorized data access or transactions. The criterion is the organization's policy on timely disabling.","Evidence: The complete HR population, ERP/directory accounts, disabling times, actual permissions, access logs and any alternative blocking.","Verify the departure and disabling times; investigate blocking at other layers and any exceptions. No activity in the logs does not eliminate the risk; also consider the possibility of incomplete logs.","The finding rests on the verified delay and its risk; a claim of theft requires additional evidence.","Closure: Retest that the notification/disabling flow has been fixed and works for subsequent real departures."],
      links:["DSS05","APO13"],rubric:["Risk and a clear criterion","Reliable/complete population and evidence","Logic of the permission and timing test","Limits of the conclusion and closure"]},
    {id:"uretim-kesintisi",title:"Why did production stop?",tag:"Integrated",time:30,story:"At ParçaNova, an ERP change causes a six-hour production planning outage. 8 of the last 30 changes have no evidence of prior approval. Backups appear successful, but there has been no restore test for 12 months. The recovery time in the provider agreement is unclear. A budget is being requested for a new tool.",
      tasks:["Write one business goal, one governance decision and two management activities.","Build a solution chain using objectives from EDM and from at least three management domains.","Define two metrics; state their source, owner and frequency.","Use at least two non-process components in your 90-day plan."],
      solution:["Business goal: Production/delivery reliability. Governance: Set direction for the risk approach and resource priorities based on business impact.","EDM03 → APO10 → BAI06 → DSS04 → MEA01 is a candidate chain; justified alternatives are possible.","8/30 means evidence of prior approval is missing in about 26.7% of cases; this is not conclusive proof that no approval was ever obtained, or that all of these changes failed.","Measures: Share of shipments delayed due to IT (monthly, logistics owner); share of future normal changes with missing preparation (weekly, change manager). Targets are agreed based on baseline data and business needs.","Days 0–30: Context, population and owners. Days 31–60: Workflow, provider terms, a recovery test that includes dependencies, and training a second person. Days 61–90: Re-evaluate operation; track actions and business benefit.","The case does not give RTO/RPO values, so do not invent them; record them as information to be determined through a business impact analysis."],
      links:["EDM03","APO10","BAI06","DSS04","MEA01"],rubric:["Distinguishing the business goal from the decision","Justified objectives chain","Control, evidence and owner","Metrics and a sustainable plan"]},
    {id:"mukerrer-fatura",title:"Two payments for the same invoice",tag:"Application control",time:25,story:"At the fictional AdaTicaret, there are two payments of similar amounts to the same vendor. Finance says there is a control that blocks duplicate invoices. The control report is exported to an Excel file. Some users can also change vendor master data. It has not yet been verified that the two payments relate to the same invoice.",
      tasks:["Separate the possible risks without making assumptions.","Write down the application control and the supporting ITGCs.","Explain how you would verify the completeness of the report and the interface.","Define a safe test and the limits of your conclusion."],
      solution:["Two similar payments are not, on their own, evidence of a duplicate payment or fraud. Verify the invoice/order/payment identifiers and the business reasons.","Application control: The duplicate invoice rule, payment authorization and master data verification. ITGC: Access that allows the rule to be changed, and change control.","Compare record counts and relevant amount totals, periods/filters and Excel transformations between the source system and the report. Request evidence of the control review and exception follow-up.","With explicit authorization, and in an appropriate test environment, assess the expected blocking, the exception path and rule changes. Do not create test invoices in production.","DSS06/APO14 cover the business/data controls; DSS05 and BAI06 cover the supporting controls. Limit the conclusion to the verified control, period and scope of evidence."],
      links:["DSS06","APO14","DSS05","BAI06"],rubric:["Separating risk from an actual event","Link between ITGCs and the application control","Report reliability and testing","Safe approach and evidence-based conclusion"]}
  ]
};
